<?php require_role('student');$pageTitle='Project Milestones';$pageSubtitle='Submit work and follow supervisor decisions';$project=project_for_student((int)current_user()['id']);$items=$project?db_all("SELECT * FROM milestones WHERE project_id=? ORDER BY id",[$project['id']]):[];include __DIR__.'/../includes/layout_top.php'; ?>
<div class="card"><div class="card-header"><div><h2>Milestone plan</h2><p>Each approved milestone contributes its weight to overall project progress.</p></div><?php if($project): ?><span class="badge success"><?= progress_for_project((int)$project['id']) ?>% approved</span><?php endif; ?></div><?php if(!$items): ?><div class="empty-state">No milestones have been configured.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Milestone</th><th>Weight</th><th>Due date</th><th>Status</th><th>Supervisor comment</th><th>Submission</th></tr></thead><tbody><?php foreach($items as $m): ?><tr><td><strong><?= e($m['title']) ?></strong><br><span class="muted"><?= e($m['description']) ?></span></td><td><?= (int)$m['weight'] ?>%</td><td><?= e(format_date($m['due_date'],'d M Y')) ?></td><td><span class="badge <?= status_class($m['status']) ?>"><?= e(str_replace('_',' ',$m['status'])) ?></span></td><td><?= e($m['supervisor_comment']?:'No comment yet') ?></td><td><?php if(in_array($m['status'],['approved'],true)): ?><span class="muted">Approved <?= e(format_date($m['approved_at'],'d M Y')) ?></span><?php else: ?><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="submit_milestone"><input type="hidden" name="milestone_id" value="<?= (int)$m['id'] ?>"><textarea name="student_note" style="min-height:70px" placeholder="State what has been completed and the document version submitted."><?= e($m['student_note']) ?></textarea><button class="button small" type="submit">Submit for review</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
